"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { setCashierSession, clearCashierSession } from "@/lib/cashier-session";
import { logActivity } from "@/lib/activity-log";
import { dispatchKitchenPrint } from "@/lib/kitchen-print";

type VerifyCashierPinRow = {
  id: string;
  business_id: string;
  name: string;
  role: "kasir" | "manajer";
};

export async function verifyPin(
  businessId: string,
  cashierId: string,
  pin: string,
): Promise<{ success: boolean; error?: string }> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .rpc("verify_cashier_pin", { p_cashier_id: cashierId, p_pin: pin })
    .single();

  if (error || !data) {
    return { success: false, error: "PIN salah, coba lagi" };
  }

  const cashier = data as VerifyCashierPinRow;

  // Defensive check: this action is called with client-supplied arguments,
  // so don't trust businessId blindly even though the RPC already scopes
  // the cashier lookup to businesses the logged-in owner owns.
  if (cashier.business_id !== businessId) {
    return { success: false, error: "PIN salah, coba lagi" };
  }

  await setCashierSession({
    cashierId: cashier.id,
    businessId: cashier.business_id,
    name: cashier.name,
    role: cashier.role,
  });

  return { success: true };
}

export async function switchCashier() {
  await clearCashierSession();
}

export type DiscountType = "pct" | "amt";

export type CartItemInput = {
  productId: string;
  qty: number;
  disc: number;
  discType: DiscountType;
};

export type CheckoutResult =
  | { success: true; invoiceNumber: string; transactionId: string }
  | { success: false; error: string };

type CheckoutRpcRow = { transaction_id: string; invoice_number: string; already_existed: boolean };

export async function checkout(
  businessId: string,
  cashierId: string,
  items: CartItemInput[],
  paymentMethod: string,
  received: number | null,
  orderDisc: number,
  orderDiscType: DiscountType,
  customerId: string | null = null,
  selfOrderIds: string[] = [],
  // Dibuat sekali di browser per penjualan (crypto.randomUUID()) dan dikirim
  // ulang apa adanya kalau ini retry dari antrian offline — RPC memakainya
  // untuk mengenali retry yang mengulang penjualan yang sebenarnya sudah
  // sukses (respons sebelumnya tidak sempat sampai ke browser), supaya tidak
  // membuat transaksi duplikat. Lihat src/hooks/use-offline-sync.ts.
  clientRef: string | null = null,
): Promise<CheckoutResult> {
  if (items.length === 0) {
    return { success: false, error: "Keranjang masih kosong." };
  }

  const supabase = await createClient();
  const { data, error } = await supabase
    .rpc("checkout_transaction", {
      p_business_id: businessId,
      p_cashier_id: cashierId,
      p_items: items.map((i) => ({
        product_id: i.productId,
        qty: i.qty,
        disc: i.disc,
        disc_type: i.discType,
      })),
      p_payment_method: paymentMethod,
      p_received: received,
      p_order_disc: orderDisc,
      p_order_disc_type: orderDiscType,
      p_customer_id: customerId,
      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
      p_client_ref: clientRef,
    })
    .single();

  if (error || !data) {
    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
  }

  const result = data as CheckoutRpcRow;

  // Retry offline yang ternyata sudah pernah sukses sebelumnya — jangan catat
  // aktivitas/cetak dapur dua kali untuk penjualan yang sama.
  if (!result.already_existed) {
    const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
    await logActivity(
      supabase,
      businessId,
      "transaksi",
      "sukses",
      `Transaksi ${result.invoice_number}`,
      `${itemCount} item · ${paymentMethod}`,
    );

    await printKitchenTicketsForItems(
      supabase,
      businessId,
      "Kasir",
      result.invoice_number,
      items.map((i) => ({ productId: i.productId, qty: i.qty })),
    );
  }

  return { success: true, invoiceNumber: result.invoice_number, transactionId: result.transaction_id };
}

async function printKitchenTicketsForItems(
  supabase: Awaited<ReturnType<typeof createClient>>,
  businessId: string,
  source: string,
  label: string,
  items: { productId: string; qty: number; note?: string | null }[],
) {
  const productIds = Array.from(new Set(items.map((i) => i.productId)));
  const { data: products } = await supabase
    .from("products")
    .select("id, name, category")
    .in("id", productIds);
  const productMap = new Map((products ?? []).map((p) => [p.id, p]));

  const failures = await dispatchKitchenPrint(supabase, businessId, {
    source,
    label,
    items: items.map((i) => ({
      name: productMap.get(i.productId)?.name ?? "Item",
      category: productMap.get(i.productId)?.category ?? null,
      qty: i.qty,
      note: i.note,
    })),
  }).catch(() => []);

  const failed = failures.filter((f) => !f.ok);
  if (failed.length > 0) {
    await logActivity(
      supabase,
      businessId,
      "sistem",
      "warning",
      `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
      failed.map((f) => f.error).join(" · "),
    );
  }
}

export type OpenShiftResult = { success: true } | { success: false; error: string };

export async function openShift(
  businessId: string,
  cashierId: string,
  openingCash: number,
  notes: string,
): Promise<OpenShiftResult> {
  const supabase = await createClient();
  const { error } = await supabase.rpc("open_shift", {
    p_business_id: businessId,
    p_cashier_id: cashierId,
    p_opening_cash: openingCash,
    p_notes: notes || null,
  });

  if (error) {
    return { success: false, error: error.message };
  }

  await logActivity(
    supabase,
    businessId,
    "sistem",
    "info",
    "Shift dibuka",
    `Kas awal Rp${openingCash.toLocaleString("id-ID")}`,
  );
  return { success: true };
}

export type CloseShiftSummary = {
  cash_sales: number;
  non_cash_sales: number;
  total_sales: number;
  expected_cash: number;
  difference: number;
  tx_count: number;
  void_count: number;
};

export type CloseShiftResult =
  | { success: true; summary: CloseShiftSummary }
  | { success: false; error: string };

export async function closeShift(
  businessId: string,
  shiftId: string,
  closingCash: number,
  closeNotes: string,
): Promise<CloseShiftResult> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .rpc("close_shift", {
      p_shift_id: shiftId,
      p_closing_cash: closingCash,
      p_close_notes: closeNotes || null,
    })
    .single();

  if (error || !data) {
    return { success: false, error: error?.message ?? "Gagal menutup shift." };
  }

  const summary = data as CloseShiftSummary;
  await logActivity(
    supabase,
    businessId,
    "sistem",
    summary.difference === 0 ? "info" : "warning",
    "Shift ditutup",
    `Penjualan Rp${summary.total_sales.toLocaleString("id-ID")} · ${summary.tx_count} transaksi · selisih Rp${summary.difference.toLocaleString("id-ID")}`,
  );
  return { success: true, summary };
}

export type OpenBillItemInput = {
  product_id: string;
  name: string;
  price: number;
  qty: number;
  disc: number;
  disc_type: DiscountType;
};

export type SaveOpenBillResult =
  | { success: true; billId: string }
  | { success: false; error: string };

export async function saveOpenBill(
  businessId: string,
  billId: string | null,
  label: string,
  items: OpenBillItemInput[],
): Promise<SaveOpenBillResult> {
  const trimmed = label.trim();
  if (!trimmed) {
    return { success: false, error: "Nama bon wajib diisi." };
  }
  if (items.length === 0) {
    return { success: false, error: "Keranjang masih kosong." };
  }

  const supabase = await createClient();

  if (billId) {
    const { error } = await supabase
      .from("open_bills")
      .update({ label: trimmed, items, updated_at: new Date().toISOString() })
      .eq("id", billId)
      .eq("business_id", businessId);
    if (error) {
      return { success: false, error: error.message };
    }
    revalidatePath(`/business/${businessId}/pos`);
    return { success: true, billId };
  }

  const { data, error } = await supabase
    .from("open_bills")
    .insert({ business_id: businessId, label: trimmed, items })
    .select("id")
    .single();

  if (error || !data) {
    return { success: false, error: error?.message ?? "Gagal menyimpan bon." };
  }

  await logActivity(
    supabase,
    businessId,
    "transaksi",
    "info",
    `Open Bill dibuat: ${trimmed}`,
    `${items.length} jenis item`,
  );
  revalidatePath(`/business/${businessId}/pos`);
  return { success: true, billId: data.id };
}

export async function deleteOpenBill(businessId: string, billId: string) {
  const supabase = await createClient();
  await supabase.from("open_bills").delete().eq("id", billId).eq("business_id", businessId);
  revalidatePath(`/business/${businessId}/pos`);
}

export async function updateSelfOrderStatus(
  businessId: string,
  orderId: string,
  status: "diproses" | "selesai",
): Promise<{ success: boolean; error?: string }> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("self_orders")
    .update({ status })
    .eq("id", orderId)
    .eq("business_id", businessId)
    .select("tables(name)")
    .single();

  if (error) {
    return { success: false, error: error.message };
  }

  const tableName =
    (data as unknown as { tables: { name: string } | null }).tables?.name ?? "Meja terhapus";
  await logActivity(
    supabase,
    businessId,
    "transaksi",
    "info",
    `Pesanan ${tableName} → ${status}`,
  );

  if (status === "diproses") {
    const { data: orderItems } = await supabase
      .from("self_order_items")
      .select("product_id, name, qty, note, products(category)")
      .eq("self_order_id", orderId);

    if (orderItems && orderItems.length > 0) {
      const failures = await dispatchKitchenPrint(supabase, businessId, {
        source: tableName,
        label: "Pesanan Self-Order",
        items: orderItems.map((i) => ({
          name: i.name,
          category: (i as unknown as { products: { category: string | null } | null }).products
            ?.category ?? null,
          qty: Number(i.qty),
          note: i.note,
        })),
      }).catch(() => []);

      const failed = failures.filter((f) => !f.ok);
      if (failed.length > 0) {
        await logActivity(
          supabase,
          businessId,
          "sistem",
          "warning",
          `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
          failed.map((f) => f.error).join(" · "),
        );
      }
    }
  }

  revalidatePath(`/business/${businessId}/pos`);
  revalidatePath(`/business/${businessId}/tables`);
  return { success: true };
}

"use client";

import { useActionState, useRef, useState, useEffect } from "react";
import type { KitchenPrinterState } from "./actions";

const initialState: KitchenPrinterState = { error: null };

export default function AddPrinterForm({
  action,
  categories,
}: {
  action: (state: KitchenPrinterState, formData: FormData) => Promise<KitchenPrinterState>;
  categories: string[];
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);
  const [connectionType, setConnectionType] = useState<"bluetooth" | "lan">("bluetooth");

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-3">
      <div>
        <label htmlFor="printer-name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Stasiun
        </label>
        <input
          id="printer-name"
          name="name"
          type="text"
          required
          placeholder="Contoh: Dapur, Bar, Bakery…"
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      <div>
        <p className="mb-1 text-xs font-medium text-zinc-600">Jenis Koneksi</p>
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => setConnectionType("bluetooth")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "bluetooth"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            📶 Bluetooth
          </button>
          <button
            type="button"
            onClick={() => setConnectionType("lan")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "lan"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            🌐 LAN / Wi-Fi
          </button>
        </div>
        <input type="hidden" name="connectionType" value={connectionType} />
      </div>

      <div>
        <label htmlFor="printer-address" className="mb-1 block text-xs font-medium text-zinc-600">
          {connectionType === "lan" ? "IP Address Printer" : "Nama Perangkat Bluetooth"}
        </label>
        <input
          id="printer-address"
          name="address"
          type="text"
          placeholder={connectionType === "lan" ? "192.168.1.101" : "Contoh: KITCHEN-80"}
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm font-mono focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      {categories.length > 0 && (
        <div>
          <p className="mb-1.5 text-xs font-medium text-zinc-600">
            Kategori Menu yang Dicetak ke Stasiun Ini
          </p>
          <div className="flex flex-wrap gap-2">
            {categories.map((c) => (
              <label
                key={c}
                className="flex items-center gap-1.5 rounded-full border border-zinc-200 bg-white px-3 py-1.5 text-xs text-zinc-700 has-checked:border-brand-500 has-checked:bg-brand-50"
              >
                <input type="checkbox" name="categories" value={c} className="h-3 w-3" />
                {c}
              </label>
            ))}
          </div>
        </div>
      )}

      {state.error && <p className="text-xs text-red-600">{state.error}</p>}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {pending ? "Menyimpan…" : "+ Tambah Printer"}
      </button>
    </form>
  );
}

