  const { data: existing } = await supabase
    .from("open_bills")
    .select("items")
    .eq("id", billId)
    .eq("business_id", businessId)
    .single();

  const { error } = await supabase
    .from("open_bills")
    .update({ label: trimmed, items, updated_at: new Date().toISOString() })
    .eq("id", billId)
    .eq("business_id", businessId);
  if (error) {
    return { success: false, error: error.message };
