  // Cetak hanya selisih (item/qty baru) ke dapur/bar — bukan cetak ulang
  // seluruh bon — supaya dapur tahu ini susulan, bukan pesanan baru.
  const oldItems = (existing?.items as OpenBillItemInput[] | null) ?? [];
  const oldQtyByProduct = new Map(oldItems.map((i) => [i.product_id, i.qty]));
