    const delta = i.qty - (oldQtyByProduct.get(i.product_id) ?? 0);
    return delta > 0 ? [{ productId: i.product_id, qty: delta }] : [];
  });
  if (addedItems.length > 0) {
    await printKitchenTicketsForItems(supabase, businessId, "Tambahan Bon", trimmed, addedItems);
  }

  revalidatePath(`/business/${businessId}/pos`);
  return { success: true, billId };
}

