"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { getPendingPrintJobCount, retryKitchenPrintQueue } from "@/app/business/[businessId]/pos/actions";

const RETRY_INTERVAL_MS = 30000;

// Polling ringan: selagi ada tiket dapur/bar yang gagal cetak sebelumnya
// (printer mati saat order masuk), coba cetak ulang tiap 30 detik sampai
// berhasil atau melewati batas percobaan. Lihat use-offline-sync.ts untuk
// pola sinkronisasi analog di sisi transaksi.
export function useKitchenPrintRetry(businessId: string) {
  const [pendingCount, setPendingCount] = useState(0);
  const retryingRef = useRef(false);

  const refresh = useCallback(async () => {
    const count = await getPendingPrintJobCount(businessId).catch(() => 0);
    setPendingCount(count);
    return count;
  }, [businessId]);

  const retryNow = useCallback(async () => {
    if (retryingRef.current) return;
    retryingRef.current = true;
    try {
      const remaining = await retryKitchenPrintQueue(businessId).catch(() => null);
      if (remaining !== null) setPendingCount(remaining);
      else await refresh();
    } finally {
      retryingRef.current = false;
    }
  }, [businessId, refresh]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (pendingCount > 0) void retryNow();
    }, RETRY_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [pendingCount, retryNow]);

  return { pendingCount, retryNow };
}

