import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import PrintButton from "./print-button";

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", { dateStyle: "medium", timeStyle: "short" });
}

type ShiftRow = {
  id: string;
  opened_at: string;
  closed_at: string | null;
  opening_cash: number;
  closing_cash: number | null;
  cash_sales: number;
  non_cash_sales: number;
  total_sales: number;
  expected_cash: number;
  difference: number;
  tx_count: number;
  void_count: number;
  cashiers: { name: string } | null;
};

export default async function ShiftReceiptPage({
  params,
  searchParams,
}: {
  params: Promise<{ businessId: string; shiftId: string }>;
  searchParams: Promise<{ menu?: string }>;
}) {
  const { businessId, shiftId } = await params;
  const { menu } = await searchParams;
  const includeMenu = menu === "1";
  const supabase = await createClient();

  const [{ data: business }, { data: shiftRow }, { data: paymentRows }] = await Promise.all([
    supabase.from("businesses").select("name").eq("id", businessId).single(),
    supabase
      .from("shifts")
      .select(
        "id, opened_at, closed_at, opening_cash, closing_cash, cash_sales, non_cash_sales, total_sales, expected_cash, difference, tx_count, void_count, cashiers(name)",
      )
      .eq("id", shiftId)
      .eq("business_id", businessId)
      .single(),
    supabase
      .from("transaction_payments")
      .select("method, amount, transactions!inner(shift_id, voided)")
      .eq("transactions.shift_id", shiftId)
      .eq("transactions.voided", false),
  ]);

  if (!business || !shiftRow) {
    notFound();
  }

  const shift = shiftRow as unknown as ShiftRow;

  const byMethod = new Map<string, number>();
  for (const p of paymentRows ?? []) {
    const method = p.method as string;
    byMethod.set(method, (byMethod.get(method) ?? 0) + Number(p.amount));
  }
  const paymentBreakdown = Array.from(byMethod.entries()).sort((a, b) => b[1] - a[1]);

  let menuBreakdown: { name: string; qty: number; total: number }[] = [];
  if (includeMenu) {
    const { data: itemRows } = await supabase
      .from("transaction_items")
      .select("name, qty, price, transactions!inner(shift_id, voided)")
      .eq("transactions.shift_id", shiftId)
      .eq("transactions.voided", false);

    const byName = new Map<string, { qty: number; total: number }>();
    for (const i of itemRows ?? []) {
      const cur = byName.get(i.name) ?? { qty: 0, total: 0 };
      cur.qty += Number(i.qty);
      cur.total += Number(i.qty) * Number(i.price);
      byName.set(i.name, cur);
    }
    menuBreakdown = Array.from(byName.entries())
      .map(([name, v]) => ({ name, ...v }))
      .sort((a, b) => b.total - a.total);
  }

  return (
    <div className="w-full max-w-xs font-mono text-xs text-zinc-900 print:max-w-none">
      <div className="print:hidden">
        <PrintButton businessId={businessId} shiftId={shiftId} includeMenu={includeMenu} />
      </div>

      <div className="mt-4 rounded-xl bg-white shadow-sm p-5 print:mt-0 print:rounded-none print:border-0 print:p-0">
        <div className="text-center">
          <p className="text-sm font-bold uppercase">{business.name}</p>
          <p className="mt-1 font-bold">LAPORAN TUTUP KASIR</p>
        </div>

        <div className="mt-3 border-t border-dashed border-zinc-300 pt-2">
          <div className="flex justify-between">
            <span>Kasir</span>
            <span>{shift.cashiers?.name ?? "—"}</span>
          </div>
          <div className="flex justify-between">
            <span>Buka</span>
            <span>{formatDateTime(shift.opened_at)}</span>
          </div>
          <div className="flex justify-between">
            <span>Tutup</span>
            <span>{shift.closed_at ? formatDateTime(shift.closed_at) : "—"}</span>
          </div>
        </div>

        <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
          <p className="font-bold">PENJUALAN PER METODE</p>
          {paymentBreakdown.length > 0 ? (
            paymentBreakdown.map(([method, amount]) => (
              <div key={method} className="flex justify-between">
                <span>{method}</span>
                <span>{formatRupiah(amount)}</span>
              </div>
            ))
          ) : (
            <p className="text-zinc-400">Tidak ada transaksi.</p>
          )}
          <div className="flex justify-between border-t border-dashed border-zinc-300 pt-1 text-sm font-bold">
            <span>TOTAL</span>
            <span>{formatRupiah(Number(shift.total_sales))}</span>
          </div>
        </div>

        <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
          <div className="flex justify-between">
            <span>Jumlah Transaksi</span>
            <span>{shift.tx_count}</span>
          </div>
          {shift.void_count > 0 && (
            <div className="flex justify-between">
              <span>Dibatalkan</span>
              <span>{shift.void_count}</span>
            </div>
          )}
          <div className="flex justify-between">
            <span>Kas Awal</span>
            <span>{formatRupiah(Number(shift.opening_cash))}</span>
          </div>
          <div className="flex justify-between">
            <span>Kas Diharapkan</span>
            <span>{formatRupiah(Number(shift.expected_cash))}</span>
          </div>
          {shift.closing_cash !== null && (
            <div className="flex justify-between">
              <span>Kas Aktual</span>
              <span>{formatRupiah(Number(shift.closing_cash))}</span>
            </div>
          )}
          <div className="flex justify-between font-bold">
            <span>Selisih</span>
            <span>
              {Number(shift.difference) === 0
                ? "Pas"
                : `${Number(shift.difference) > 0 ? "+" : ""}${formatRupiah(Number(shift.difference))}`}
            </span>
          </div>
        </div>

        {includeMenu && (
          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            <p className="font-bold">PENJUALAN PER MENU</p>
            {menuBreakdown.length > 0 ? (
              menuBreakdown.map((m) => (
                <div key={m.name} className="flex justify-between gap-2">
                  <span className="flex-1 truncate">
                    {m.name} <span className="text-zinc-500">x{m.qty}</span>
                  </span>
                  <span className="shrink-0">{formatRupiah(m.total)}</span>
                </div>
              ))
            ) : (
              <p className="text-zinc-400">Tidak ada transaksi.</p>
            )}
          </div>
        )}

        <p className="mt-4 border-t border-dashed border-zinc-300 pt-2 text-center">
          Dicetak {formatDateTime(new Date().toISOString())}
        </p>
      </div>
    </div>
  );
}

