"use client";

import { useEffect, useRef } from "react";
import Link from "next/link";

export default function PrintButton({
  businessId,
  shiftId,
  includeMenu,
}: {
  businessId: string;
  shiftId: string;
  includeMenu: boolean;
}) {
  const printed = useRef(false);
  useEffect(() => {
    if (printed.current) return;
    printed.current = true;
    window.print();
  }, []);

  return (
    <div className="space-y-2">
      <div className="flex gap-2">
        <Link
          href={`/business/${businessId}/shifts`}
          className="flex flex-1 items-center justify-center rounded-xl border border-zinc-200 bg-white py-2.5 text-sm font-medium text-zinc-600 hover:bg-zinc-50"
        >
          ← Kembali
        </Link>
        <button
          onClick={() => window.print()}
          className="flex-1 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white hover:bg-brand-700"
        >
          🖨️ Cetak
        </button>
      </div>
      {!includeMenu && (
        <Link
          href={`/business/${businessId}/shifts/${shiftId}/receipt?menu=1`}
          className="block w-full rounded-xl border border-zinc-200 bg-white py-2 text-center text-xs font-medium text-zinc-600 hover:bg-zinc-50"
        >
          + Sertakan laporan per menu
        </Link>
      )}
    </div>
  );
}

