import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}

type ShiftRow = {
  id: string;
  opened_at: string;
  closed_at: string;
  opening_cash: number;
  closing_cash: number;
  cash_sales: number;
  non_cash_sales: number;
  total_sales: number;
  expected_cash: number;
  difference: number;
  tx_count: number;
  void_count: number;
  close_notes: string | null;
  cashiers: { name: string } | null;
};

export default async function ShiftsPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: shiftRows } = await supabase
    .from("shifts")
    .select(
      "id, opened_at, closed_at, opening_cash, closing_cash, cash_sales, non_cash_sales, total_sales, expected_cash, difference, tx_count, void_count, close_notes, cashiers(name)",
    )
    .eq("business_id", businessId)
    .not("closed_at", "is", null)
    .order("closed_at", { ascending: false })
    .limit(50);

  const shifts = (shiftRows ?? []) as unknown as ShiftRow[];

  return (
    <div className="w-full max-w-2xl">
        <h1 className="text-lg font-bold text-zinc-900">
          Riwayat Shift — {business.name}
        </h1>
        <p className="mt-1 text-sm text-zinc-500">50 shift terakhir yang sudah ditutup.</p>

        <div className="mt-6 space-y-2">
          {shifts.length > 0 ? (
            shifts.map((s) => {
              const diff = Number(s.difference);
              return (
                <div
                  key={s.id}
                  className="rounded-xl border border-zinc-200 bg-white px-4 py-3"
                >
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium text-zinc-900">
                      {s.cashiers?.name ?? "Kasir terhapus"}
                    </p>
                    <p className="text-sm font-semibold text-zinc-900">
                      {formatRupiah(Number(s.total_sales))}
                    </p>
                  </div>
                  <p className="mt-0.5 text-xs text-zinc-500">
                    {formatDateTime(s.opened_at)} – {formatDateTime(s.closed_at)}
                  </p>

                  <div className="mt-2 grid grid-cols-3 gap-2 rounded-lg bg-zinc-50 px-3 py-2 text-center">
                    <div>
                      <p className="text-[10px] text-zinc-400">Transaksi</p>
                      <p className="text-xs font-semibold text-zinc-900">{s.tx_count}</p>
                    </div>
                    <div>
                      <p className="text-[10px] text-zinc-400">Kas Diharapkan</p>
                      <p className="text-xs font-semibold text-zinc-900">
                        {formatRupiah(Number(s.expected_cash))}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-zinc-400">Selisih</p>
                      <p
                        className={`text-xs font-semibold ${
                          diff === 0
                            ? "text-zinc-900"
                            : diff > 0
                              ? "text-brand-700"
                              : "text-red-600"
                        }`}
                      >
                        {diff === 0 ? "Pas" : `${diff > 0 ? "+" : ""}${formatRupiah(diff)}`}
                      </p>
                    </div>
                  </div>

                  {s.void_count > 0 && (
                    <p className="mt-1.5 text-[11px] text-red-500">
                      {s.void_count} transaksi dibatalkan
                    </p>
                  )}
                  {s.close_notes && (
                    <p className="mt-1.5 text-[11px] text-zinc-400">Catatan: {s.close_notes}</p>
                  )}
                </div>
              );
            })
          ) : (
            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
              Belum ada shift yang ditutup.
            </p>
          )}
        </div>
    </div>
  );
}

"use client";

import { useActionState, useRef, useState, useEffect } from "react";
import type { KitchenPrinterState } from "./actions";

const initialState: KitchenPrinterState = { error: null };

export default function AddPrinterForm({
  action,
  categories,
}: {
  action: (state: KitchenPrinterState, formData: FormData) => Promise<KitchenPrinterState>;
  categories: string[];
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);
  const [connectionType, setConnectionType] = useState<"bluetooth" | "lan">("bluetooth");

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-3">
      <div>
        <label htmlFor="printer-name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Stasiun
        </label>
        <input
          id="printer-name"
          name="name"
          type="text"
          required
          placeholder="Contoh: Dapur, Bar, Bakery…"
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      <div>
        <p className="mb-1 text-xs font-medium text-zinc-600">Jenis Koneksi</p>
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => setConnectionType("bluetooth")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "bluetooth"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            📶 Bluetooth
          </button>
          <button
            type="button"
            onClick={() => setConnectionType("lan")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "lan"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            🌐 LAN / Wi-Fi
          </button>
        </div>
        <input type="hidden" name="connectionType" value={connectionType} />
      </div>

      <div>
        <label htmlFor="printer-address" className="mb-1 block text-xs font-medium text-zinc-600">
          {connectionType === "lan" ? "IP Address Printer" : "Nama Perangkat Bluetooth"}
        </label>
        <input
          id="printer-address"
          name="address"
          type="text"
          placeholder={connectionType === "lan" ? "192.168.1.101" : "Contoh: KITCHEN-80"}
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm font-mono focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      {categories.length > 0 && (
        <div>
          <p className="mb-1.5 text-xs font-medium text-zinc-600">
            Kategori Menu yang Dicetak ke Stasiun Ini
          </p>
          <div className="flex flex-wrap gap-2">
            {categories.map((c) => (
              <label
                key={c}
                className="flex items-center gap-1.5 rounded-full border border-zinc-200 bg-white px-3 py-1.5 text-xs text-zinc-700 has-checked:border-brand-500 has-checked:bg-brand-50"
              >
                <input type="checkbox" name="categories" value={c} className="h-3 w-3" />
                {c}
              </label>
            ))}
          </div>
        </div>
      )}

      {state.error && <p className="text-xs text-red-600">{state.error}</p>}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {pending ? "Menyimpan…" : "+ Tambah Printer"}
      </button>
    </form>
  );
}

