"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { parseCsv } from "@/lib/csv";
import { logActivity } from "@/lib/activity-log";

export type ImportTransactionsState = {
  error: string | null;
  result: { created: number; skipped: number; errors: string[] } | null;
};

// One CSV row = one line item; rows sharing the same "Referensi" are grouped
// into a single multi-item transaction (transactions have many items, unlike
// products' one-row-one-entity import). Product/customer must already exist
// — this doesn't auto-create them, unlike importProducts.
const IMPORT_COLUMNS = ["reference", "date", "productName", "qty", "paymentMethod", "customerName"] as const;

export async function importTransactions(
  businessId: string,
  _prevState: ImportTransactionsState,
  formData: FormData,
): Promise<ImportTransactionsState> {
  const file = formData.get("file") as File | null;
  if (!file || file.size === 0) {
    return { error: "Pilih file CSV dulu.", result: null };
  }

  const text = await file.text();
  const rows = parseCsv(text).filter((r) => r.some((c) => c.trim() !== ""));
  if (rows.length < 2) {
    return { error: "File CSV kosong atau cuma berisi header.", result: null };
  }

  const dataRows = rows.slice(1);
  const supabase = await createClient();

  const [{ data: products }, { data: customers }] = await Promise.all([
    supabase
      .from("products")
      .select("id, name")
      .eq("business_id", businessId)
      .is("deleted_at", null),
    supabase
      .from("customers")
      .select("id, name")
      .eq("business_id", businessId)
      .is("deleted_at", null),
  ]);

  const productIdByName = new Map(
    (products ?? []).map((p) => [p.name.trim().toLowerCase(), p.id]),
  );
  const customerIdByName = new Map(
    (customers ?? []).map((c) => [c.name.trim().toLowerCase(), c.id]),
  );

  type ParsedRow = {
    line: number;
    reference: string;
    date: string;
    productName: string;
    qty: number;
    paymentMethod: string;
    customerName: string;
  };

  const errors: string[] = [];
  const groups = new Map<string, ParsedRow[]>();

  for (let i = 0; i < dataRows.length; i++) {
    const row = dataRows[i];
    const line = i + 2;
    const get = (col: (typeof IMPORT_COLUMNS)[number]) =>
      row[IMPORT_COLUMNS.indexOf(col)]?.trim() || "";

    const reference = get("reference");
    if (!reference) {
      errors.push(`Baris ${line}: Referensi kosong`);
      continue;
    }
    const date = get("date");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      errors.push(`Baris ${line}: tanggal harus format YYYY-MM-DD`);
      continue;
    }
    const productName = get("productName");
    if (!productName) {
      errors.push(`Baris ${line}: nama produk kosong`);
      continue;
    }
    const qty = Number(get("qty"));
    if (!get("qty") || Number.isNaN(qty) || qty <= 0) {
      errors.push(`Baris ${line}: qty tidak valid`);
      continue;
    }
    const paymentMethod = get("paymentMethod");
    if (!paymentMethod) {
      errors.push(`Baris ${line}: metode bayar kosong`);
      continue;
    }
    const customerName = get("customerName");

    const list = groups.get(reference) ?? [];
    list.push({ line, reference, date, productName, qty, paymentMethod, customerName });
    groups.set(reference, list);
  }

  let created = 0;
  let skipped = 0;

  for (const [reference, groupRows] of groups) {
    const first = groupRows[0];
    const mismatched = groupRows.find(
      (r) =>
        r.date !== first.date ||
        r.paymentMethod !== first.paymentMethod ||
        r.customerName !== first.customerName,
    );
    if (mismatched) {
      skipped += groupRows.length;
      errors.push(
        `Referensi "${reference}": tanggal/metode bayar/pelanggan tidak konsisten antar baris (baris ${mismatched.line})`,
      );
      continue;
    }

    let customerId: string | null = null;
    if (first.customerName) {
      customerId = customerIdByName.get(first.customerName.toLowerCase()) ?? null;
      if (!customerId) {
        skipped += groupRows.length;
        errors.push(`Referensi "${reference}": pelanggan "${first.customerName}" tidak ditemukan`);
        continue;
      }
    }

    const items: { product_id: string; qty: number }[] = [];
    let productMissing = false;
    for (const r of groupRows) {
      const productId = productIdByName.get(r.productName.toLowerCase());
      if (!productId) {
        errors.push(`Baris ${r.line}: produk "${r.productName}" tidak ditemukan`);
        productMissing = true;
        continue;
      }
      items.push({ product_id: productId, qty: r.qty });
    }
    if (productMissing || items.length === 0) {
      skipped += groupRows.length;
      continue;
    }

    const { error } = await supabase.rpc("create_manual_transaction", {
      p_business_id: businessId,
      p_date: new Date(`${first.date}T12:00:00`).toISOString(),
      p_items: items,
      p_payment_method: first.paymentMethod,
      p_received: null,
      p_customer_id: customerId,
    });

    if (error) {
      skipped += groupRows.length;
      errors.push(`Referensi "${reference}": ${error.message}`);
      continue;
    }

    created++;
  }

  if (created > 0) {
    await logActivity(
      supabase,
      businessId,
      "transaksi",
      "sukses",
      `Impor transaksi: ${created} transaksi baru`,
      skipped > 0 ? `${skipped} baris dilewati` : undefined,
    );
    revalidatePath(`/business/${businessId}/transactions`);
  }

  return { error: null, result: { created, skipped, errors } };
}

import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import PrintButton from "./print-button";

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", {
    dateStyle: "medium",
    timeStyle: "short",
  });
}

export default async function ReceiptPage({
  params,
}: {
  params: Promise<{ businessId: string; transactionId: string }>;
}) {
  const { businessId, transactionId } = await params;
  const supabase = await createClient();

  // Keempat query tidak saling bergantung (semua cuma butuh businessId/
  // transactionId dari params) — dijalankan paralel, bukan berurutan,
  // supaya struk render lebih cepat begitu dibuka dari POS.
  const [{ data: business }, { data: transaction }, { data: items }, { data: payments }] =
    await Promise.all([
      supabase.from("businesses").select("name").eq("id", businessId).single(),
      supabase
        .from("transactions")
        .select(
          "id, invoice_number, date, subtotal_raw, subtotal, service, tax, total_item_disc, order_disc_amt, total, voided, cashiers!transactions_cashier_id_fkey(name)",
        )
        .eq("id", transactionId)
        .eq("business_id", businessId)
        .single(),
      supabase
        .from("transaction_items")
        .select("id, name, price, qty")
        .eq("transaction_id", transactionId)
        .order("id", { ascending: true }),
      supabase
        .from("transaction_payments")
        .select("id, method, amount, received, change")
        .eq("transaction_id", transactionId),
    ]);

  if (!business || !transaction) {
    notFound();
  }

  return (
    <div className="w-full max-w-xs font-mono text-xs text-zinc-900 print:max-w-none">
        <div className="print:hidden">
          <PrintButton businessId={businessId} transactionId={transactionId} />
        </div>

        <div className="mt-4 rounded-xl bg-white shadow-sm p-5 print:mt-0 print:rounded-none print:border-0 print:p-0">
          <div className="text-center">
            <p className="text-sm font-bold uppercase">{business.name}</p>
            {transaction.voided && (
              <p className="mt-1 font-bold text-red-600">*** DIBATALKAN ***</p>
            )}
          </div>

          <div className="mt-3 border-t border-dashed border-zinc-300 pt-2">
            <div className="flex justify-between">
              <span>No.</span>
              <span>{transaction.invoice_number}</span>
            </div>
            <div className="flex justify-between">
              <span>Tanggal</span>
              <span>{formatDateTime(transaction.date)}</span>
            </div>
            <div className="flex justify-between">
              <span>Kasir</span>
              <span>
                {(transaction.cashiers as unknown as { name: string } | null)?.name ?? "—"}
              </span>
            </div>
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            {items?.map((item) => (
              <div key={item.id} className="flex justify-between gap-2">
                <span className="flex-1 truncate">
                  {item.name}
                  <span className="text-zinc-500">
                    {" "}
                    {item.qty}x{Number(item.price).toLocaleString("id-ID")}
                  </span>
                </span>
                <span className="shrink-0">
                  {formatRupiah(Number(item.price) * Number(item.qty))}
                </span>
              </div>
            ))}
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            <div className="flex justify-between">
              <span>Subtotal</span>
              <span>{formatRupiah(Number(transaction.subtotal_raw))}</span>
            </div>
            {Number(transaction.total_item_disc) > 0 && (
              <div className="flex justify-between">
                <span>Diskon item</span>
                <span>-{formatRupiah(Number(transaction.total_item_disc))}</span>
              </div>
            )}
            {Number(transaction.order_disc_amt) > 0 && (
              <div className="flex justify-between">
                <span>Diskon order</span>
                <span>-{formatRupiah(Number(transaction.order_disc_amt))}</span>
              </div>
            )}
            {Number(transaction.service) > 0 && (
              <div className="flex justify-between">
                <span>Layanan</span>
                <span>{formatRupiah(Number(transaction.service))}</span>
              </div>
            )}
            {Number(transaction.tax) > 0 && (
              <div className="flex justify-between">
                <span>PPN</span>
                <span>{formatRupiah(Number(transaction.tax))}</span>
              </div>
            )}
            <div className="flex justify-between border-t border-dashed border-zinc-300 pt-1 text-sm font-bold">
              <span>TOTAL</span>
              <span>{formatRupiah(Number(transaction.total))}</span>
            </div>
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            {payments?.map((p) => (
              <div key={p.id}>
                <div className="flex justify-between">
                  <span>{p.method}</span>
                  <span>{formatRupiah(Number(p.amount))}</span>
                </div>
                {p.received !== null && (
                  <div className="flex justify-between">
                    <span>Diterima</span>
                    <span>{formatRupiah(Number(p.received))}</span>
                  </div>
                )}
                {p.change !== null && Number(p.change) > 0 && (
                  <div className="flex justify-between">
                    <span>Kembalian</span>
                    <span>{formatRupiah(Number(p.change))}</span>
                  </div>
                )}
              </div>
            ))}
          </div>

          <p className="mt-4 border-t border-dashed border-zinc-300 pt-2 text-center">
            Terima kasih!
          </p>
        </div>
    </div>
  );
}

