"use client";

import { useEffect, useMemo, useState, type KeyboardEvent } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  addShiftCashMovement,
  checkout,
  closeShift,
  deleteOpenBill,
  getSelfOrders,
  saveOpenBill,
  updateSelfOrderStatus,
  type CheckoutResult,
  type CloseShiftSummary,
  type DiscountType,
} from "./actions";
import SwitchCashierButton from "./switch-cashier-button";
import OfflineStatus from "./offline-status";
import { itemDiscAmount, calculateCheckoutTotals } from "@/lib/checkout-totals";
import { useOfflineSync } from "@/hooks/use-offline-sync";
import { enqueueSale, pendingStockDeltas } from "@/lib/offline-queue";
import { withTimeout } from "@/lib/with-timeout";
import { dispatchPrintJobs, dispatchReceiptThenKitchenJobs } from "@/lib/dispatch-print-jobs";
import { Capacitor } from "@capacitor/core";

type Product = {
  id: string;
  name: string;
  category: string | null;
  price: number;
  cost: number;
  stock: number;
  emoji: string | null;
  barcode: string | null;
  sku: string | null;
  variant_label: string | null;
};

type CartItem = {
  productId: string;
  name: string;
  price: number;
  qty: number;
  maxStock: number;
  disc: number;
  discType: DiscountType;
};

type SelfOrder = {
  id: string;
  status: "baru" | "diproses";
  createdAt: string;
  tableName: string;
  items: {
    productId: string | null;
    name: string;
    qty: number;
    price: number;
    note: string | null;
  }[];
};

type OpenBill = {
  id: string;
  label: string;
  updated_at: string;
  items: {
    product_id: string;
    name: string;
    price: number;
    qty: number;
    disc: number;
    disc_type: DiscountType;
  }[];
};

type Customer = {
  id: string;
  name: string;
  phone: string | null;
};

const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

export default function PosScreen({
  businessId,
  businessName,
  cashierId,
  cashierName,
  shiftId,
  products,
  taxRate,
  serviceRate,
  openBills,
  customers,
  isFnb,
  selfOrders: initialSelfOrders,
  customPaymentMethods,
}: {
  businessId: string;
  businessName: string;
  cashierId: string;
  cashierName: string;
  shiftId: string;
  products: Product[];
  taxRate: number;
  serviceRate: number;
  openBills: OpenBill[];
  customers: Customer[];
  isFnb: boolean;
  selfOrders: SelfOrder[];
  customPaymentMethods: string[];
}) {
  const router = useRouter();
  const paymentMethods = useMemo(
    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
    [customPaymentMethods],
  );
  const [search, setSearch] = useState("");
  const [scanFeedback, setScanFeedback] = useState<string | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [cartOrderIds, setCartOrderIds] = useState<string[]>([]);
  const [inboxOpen, setInboxOpen] = useState(false);
  const [inboxNotice, setInboxNotice] = useState<string | null>(null);
  const [orderBusyId, setOrderBusyId] = useState<string | null>(null);
  const [editingDiscId, setEditingDiscId] = useState<string | null>(null);
  const [orderDisc, setOrderDisc] = useState(0);
  const [orderDiscType, setOrderDiscType] = useState<DiscountType>("pct");
  const [orderDiscOpen, setOrderDiscOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [customerPickerOpen, setCustomerPickerOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState("");
  const [billsOpen, setBillsOpen] = useState(false);
  const [posMenuOpen, setPosMenuOpen] = useState(false);
  // Laporan lives in the full backoffice sidebar, which the native app never
  // exposes (see dashboard-shell.tsx) — hide the link here too so it's not a
  // dead end that lands on "Akses Ditolak".
  const isNative = Capacitor.isNativePlatform();
  const [billBusyId, setBillBusyId] = useState<string | null>(null);
  const [activeBill, setActiveBill] = useState<{ id: string; label: string } | null>(null);
  const [saveBonOpen, setSaveBonOpen] = useState(false);
  const [bonLabel, setBonLabel] = useState("");
  const [bonError, setBonError] = useState<string | null>(null);
  const [bonSaving, setBonSaving] = useState(false);

  // State lokal, disinkronkan dari prop server tiap kali props berubah (mis.
  // router.refresh() di tempat lain) — supaya polling ringan di bawah bisa
  // menimpanya sendiri tanpa saling menunggu.
  const [selfOrders, setSelfOrders] = useState(initialSelfOrders);
  useEffect(() => {
    setSelfOrders(initialSelfOrders);
  }, [initialSelfOrders]);

  const newOrderCount = selfOrders.filter((o) => o.status === "baru").length;

  // Order self-order masuk dari perangkat pelanggan; poll supaya badge kasir
  // ikut terbarui tanpa reload manual. Dulu ini panggil router.refresh() tiap
  // 15 detik — me-refresh SELURUH halaman (produk, open bill, customer, dst
  // ikut di-fetch ulang), salah satu penyebab utama app terasa lemot. Sekarang
  // cuma ambil self_orders sendirian lewat getSelfOrders().
  useEffect(() => {
    if (!isFnb) return;
    const interval = setInterval(() => {
      void getSelfOrders(businessId).then(setSelfOrders).catch(() => {});
    }, 15000);
    return () => clearInterval(interval);
  }, [isFnb, businessId]);
  const [paying, setPaying] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
  const [received, setReceived] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
  const [successTransactionId, setSuccessTransactionId] = useState<string | null>(null);
  const [successOffline, setSuccessOffline] = useState(false);

