import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { getCashierSession } from "@/lib/cashier-session";
import PinScreen from "./pin-screen";
import OpenShiftScreen from "./open-shift-screen";
import PosScreen from "./pos-screen";
import TicketPosScreen from "./ticket-pos-screen";

export default async function PosPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  // business (DB) and the cashier session (a cookie read, not a query) don't
  // depend on each other — fire both at once instead of waiting in sequence.
  const [{ data: business }, session] = await Promise.all([
    supabase
      .from("businesses")
      .select(
        "id, name, business_type, tax_enabled, tax_rate, service_enabled, service_rate",
      )
      .eq("id", businessId)
      .single(),
    getCashierSession(businessId),
  ]);

  if (!business) {
    notFound();
  }

  if (!session) {
    const { data: cashiers } = await supabase
      .from("cashiers")
      .select("id, name, role")
      .eq("business_id", businessId)
      .eq("active", true)
      .order("created_at", { ascending: true });

    return (
      <PinScreen
        businessId={businessId}
        businessName={business.name}
        cashiers={cashiers ?? []}
      />
    );
  }

  const { data: activeShift } = await supabase
    .from("shifts")
    .select("id, opening_cash, opened_at")
    .eq("business_id", businessId)
    .is("closed_at", null)
    .maybeSingle();

  if (!activeShift) {
    return (
      <OpenShiftScreen
        businessId={businessId}
        businessName={business.name}
        cashierId={session.cashierId}
        cashierName={session.name}
      />
    );
  }

  if (business.business_type === "tiket") {
    const todayStr = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
    const dayOfWeek = new Date(`${todayStr}T00:00:00`).getDay();

    // None of these 4 queries depend on each other's results — run together.
    const [
      { data: categoryRows },
      { data: customPaymentMethodRowsForTiket },
      { data: memberRows },
      { data: holidayRow },
    ] = await Promise.all([
      supabase
        .from("ticket_categories")
        .select(
          "id, name, price_weekday, price_holiday, member_price, group_min_qty, group_price",
        )
        .eq("business_id", businessId)
        .eq("active", true)
        .is("deleted_at", null)
        .order("name", { ascending: true }),
      supabase
        .from("custom_payment_methods")
        .select("name")
        .eq("business_id", businessId)
        .order("name", { ascending: true }),
      supabase
        .from("members")
        .select("id, name, phone, member_code, valid_from, valid_until")
        .eq("business_id", businessId)
        .is("deleted_at", null)
        .order("name", { ascending: true }),
      supabase
        .from("ticket_holidays")
        .select("id")
        .eq("business_id", businessId)
        .eq("holiday_date", todayStr)
        .maybeSingle(),
    ]);
    const isHoliday = dayOfWeek === 0 || dayOfWeek === 6 || !!holidayRow;

    return (
      <TicketPosScreen
        businessId={businessId}
        businessName={business.name}
        cashierId={session.cashierId}
        cashierName={session.name}
        shiftId={activeShift.id}
        categories={(categoryRows ?? []).map((c) => ({
          id: c.id,
          name: c.name,
          priceWeekday: Number(c.price_weekday),
          priceHoliday: Number(c.price_holiday),
          memberPrice: Number(c.member_price),
          groupMinQty: Number(c.group_min_qty),
          groupPrice: c.group_price == null ? null : Number(c.group_price),
        }))}
        members={(memberRows ?? []).map((m) => ({
          id: m.id,
          name: m.name,
          phone: m.phone,
          memberCode: m.member_code,
          validFrom: m.valid_from,
          validUntil: m.valid_until,
        }))}
        taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
        serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
        isHoliday={isHoliday}
        customPaymentMethods={(customPaymentMethodRowsForTiket ?? []).map((m) => m.name)}
      />
    );
  }

  const isFnb = business.business_type === "fnb";

  // Same idea as the ticket branch above — these queries are independent, so
  // self_orders (FnB only) rides in the same Promise.all batch instead of a
  // separate round trip after it — that used to be a real extra waterfall
  // on every POS page load for F&B businesses.
  const [
    { data: products },
    { data: openBillRows },
    { data: customers },
    { data: customPaymentMethodRows },
    { data: selfOrderRows },
  ] = await Promise.all([
    supabase
      .from("products")
      .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
      .eq("business_id", businessId)
      .is("deleted_at", null)
      .order("name", { ascending: true }),
    supabase
      .from("open_bills")
      .select("id, label, items, updated_at")
      .eq("business_id", businessId)
      .order("updated_at", { ascending: false }),
    supabase
      .from("customers")
      .select("id, name, phone")
      .eq("business_id", businessId)
      .is("deleted_at", null)
      .order("name", { ascending: true }),
    supabase
      .from("custom_payment_methods")
      .select("name")
      .eq("business_id", businessId)
      .order("name", { ascending: true }),
    isFnb
      ? supabase
          .from("self_orders")
          .select(
            "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
          )
          .eq("business_id", businessId)
          .neq("status", "selesai")
          .order("created_at", { ascending: true })
      : Promise.resolve({ data: null }),
  ]);

  const selfOrders = (selfOrderRows ?? []) as unknown as SelfOrderRow[];

  return (
    <PosScreen
      businessId={businessId}
      businessName={business.name}
      cashierId={session.cashierId}
      cashierName={session.name}
      shiftId={activeShift.id}
      products={products ?? []}
      taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
      serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
      openBills={(openBillRows ?? []) as unknown as OpenBillRow[]}
      customers={customers ?? []}
      isFnb={isFnb}
      customPaymentMethods={(customPaymentMethodRows ?? []).map((m) => m.name)}
      selfOrders={selfOrders.map((o) => ({
        id: o.id,
        status: o.status,
        createdAt: o.created_at,
        tableName: o.tables?.name ?? "Meja terhapus",
        items: o.self_order_items.map((i) => ({
          productId: i.product_id,
          name: i.name,
          qty: i.qty,
          price: i.price,
          note: i.note,
        })),
      }))}
    />
  );
}

type OpenBillRow = {
  id: string;
  label: string;
  updated_at: string;
  items: {
    product_id: string;
    name: string;
    price: number;
    qty: number;
    disc: number;
    disc_type: "pct" | "amt";
  }[];
};

type SelfOrderRow = {
  id: string;
  status: "baru" | "diproses";
  created_at: string;
  tables: { name: string } | null;
  self_order_items: {
    product_id: string | null;
    name: string;
    qty: number;
    price: number;
    note: string | null;
  }[];
};

