  const req = indexedDB.open("kasirku-offline", 2);
  req.onsuccess = () => {
    const db = req.result;
    const tx = db.transaction("pos_cache", "readonly");
    const getReq = tx.objectStore("pos_cache").get("b93a088f-15c3-4147-b29a-1342235ab855");
    getReq.onsuccess = () => resolve(JSON.stringify({ found: !!getReq.result, productCount: getReq.result?.products?.length }));
