  const req = indexedDB.open("kasirku-offline", 3);
  req.onupgradeneeded = () => {
    const db = req.result;
    if (!db.objectStoreNames.contains("pending_prints")) {
      const s = db.createObjectStore("pending_prints", { keyPath: "id" });
      s.createIndex("by-business", "businessId", { unique: false });
    }
  };
  req.onsuccess = () => {
    const db = req.result;
    const tx = db.transaction("pending_prints", "readwrite");
    tx.objectStore("pending_prints").put({
      id: crypto.randomUUID(),
      businessId: "b93a088f-15c3-4147-b29a-1342235ab855",
      createdAt: new Date().toISOString(),
      attempts: 3,
      status: "pending",
      errorMessage: "connect_timeout",
      job: { printerName: "Dapur Test (seed)", address: "10.255.255.1:9100", connectionType: "lan", bytesBase64: "AAAA" }
    });
    tx.oncomplete = () => resolve("seeded");
    tx.onerror = () => resolve("error: " + tx.error);
  };
  req.onerror = () => resolve("open error: " + req.error);
})

new Promise((resolve) => {
  const req = indexedDB.open("kasirku-offline", 3);
  req.onsuccess = () => {
    const db = req.result;
    const tx = db.transaction("pending_prints", "readonly");
    const getAll = tx.objectStore("pending_prints").getAll();
    getAll.onsuccess = () => resolve(JSON.stringify(getAll.result));
  };
})

new Promise((resolve) => {
  const req = indexedDB.open("kasirku-offline", 3);
  req.onsuccess = () => {
    const db = req.result;
    const tx = db.transaction("pending_prints", "readwrite");
    tx.objectStore("pending_prints").clear();
    tx.oncomplete = () => resolve("cleared");
  };
})

