3	import { Capacitor } from "@capacitor/core";
4	import { printViaAgent, type PrintAgentResult } from "./print-agent-client";
5	import KitchenPrinter from "./kitchen-printer-plugin";
6	import type { KitchenPrintJobPayload } from "./kitchen-print";
7	import { logKitchenPrintFailures } from "@/app/business/[businessId]/pos/actions";
8	
9	// Android app (android-app/) supplies KitchenPrinter natively — the browser
10	// on the cashier's own tablet is on the shop's LAN (or physically holding
11	// it, for Bluetooth), so it can dial the printer directly, no print-agent PC
12	// needed. Plain browsers keep using the print-agent HTTP relay for LAN jobs
13	// (untouched); they have no way to reach a bluetooth job at all.
14	async function dispatchOne(job: KitchenPrintJobPayload): Promise<PrintAgentResult> {
15	  if (Capacitor.isNativePlatform()) {
16	    const result =
17	      job.connectionType === "lan"
18	        ? await (() => {
19	            const [ip, portStr] = job.address.split(":");
20	            const port = portStr ? Number(portStr) : 9100;
21	            return KitchenPrinter.printLan({ ip, port, bytesBase64: job.bytesBase64 });
22	          })()
23	        : await KitchenPrinter.printBluetooth({ address: job.address, bytesBase64: job.bytesBase64 });
24	    return result.ok
25	      ? { ok: true }
26	      : { ok: false, reason: "printer_unreachable", error: result.error ?? "unknown_error" };
27	  }
28	  if (job.connectionType === "bluetooth") {
29	    return { ok: false, reason: "printer_unreachable", error: "unsupported_on_web" };
30	  }
31	  return printViaAgent(job.address, job.bytesBase64);
32	}
33	
34	export type DispatchedPrintResult = { job: KitchenPrintJobPayload; result: PrintAgentResult };
35	
36	// Fire-and-forget from the checkout/order-status callers' point of view — a
37	// failed kitchen print must never block or fail the sale/order that
38	// triggered it (same principle the old server-side dispatchKitchenPrint
39	// followed), so they just `void` this call. The return value exists for
40	// callers that DO want to know per-job success/failure inline (e.g. a
41	// "Tes Cetak" button) — existing fire-and-forget callers are unaffected.
42	export async function dispatchPrintJobs(
43	  businessId: string,
44	  jobs: KitchenPrintJobPayload[],
45	): Promise<DispatchedPrintResult[]> {
46	  if (jobs.length === 0) return [];
47	
48	  const results = await Promise.all(
49	    jobs.map(async (job) => ({ job, result: await dispatchOne(job) })),
50	  );
51	
52	  const failed = results.filter((r) => !r.result.ok);
53	  if (failed.length > 0) {
54	    await logKitchenPrintFailures(
55	      businessId,
56	      failed.map(({ job, result }) => ({
57	        printer: job.printerName,
58	        error: result.ok ? "" : result.error,
59	      })),
60	    ).catch(() => {});
61	  }
62	
63	  return results;
64	}
65	
66	// Receipt jobs go out first and are awaited before the kitchen jobs start —
67	// two reasons: the cashier's receipt printer is often the same physical
68	// device as a kitchen station (Bluetooth sockets don't handle concurrent
69	// jobs well), and the customer copy is the priority print, not the kitchen
70	// ticket.
71	export async function dispatchReceiptThenKitchenJobs(
72	  businessId: string,
73	  receiptJobs: KitchenPrintJobPayload[],
74	  kitchenJobs: KitchenPrintJobPayload[],
75	) {
76	  await dispatchPrintJobs(businessId, receiptJobs);
77	  await dispatchPrintJobs(businessId, kitchenJobs);
78	}
